  title = excluded.title,
  short_desc = excluded.short_desc,
  icon = excluded.icon,
  full_content = excluded.full_content,
  benefits = excluded.benefits,
  process_steps = excluded.process_steps,
  faq = excluded.faq,
  order_index = excluded.order_index;

